class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (n + 1)

    def update(self, index, value):
        index += 1
        while index <= self.n:
            self.tree[index] += value
            index += index & (-index)

    def query(self, index):
        result = 0
        index += 1
        while index > 0:
            result += self.tree[index]
            index -= index & (-index)
        return result

def fast_sum(numbers):
